from AlgorithmImports import *
import math


class IndependentDailyStrategies(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_closes = RollingWindow[float](101)
        self.aapl_closes = RollingWindow[float](4)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.aapl_red_streak = 0

        self.strategy_a_percent = 0.10
        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.pending_orders = {}
        self.strategy_a_pending = False
        self.strategy_b_pending = False

    def OnData(self, data: Slice):
        for symbol in self.symbols:
            if symbol not in data.Bars:
                continue

            close = float(data.Bars[symbol].Close)

            if symbol == self.spy:
                self.spy_closes.Add(close)

            elif symbol == self.aapl:
                previous_close = self.aapl_closes[0] if self.aapl_closes.Count > 0 else None
                self.aapl_closes.Add(close)
                self.aapl_rsi.Update(IndicatorDataPoint(symbol, data.Time, close))

                if previous_close is not None and close < previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

        if any(symbol not in data.Bars for symbol in self.symbols):
            return

        if self.spy_closes.Count < 101 or not self.aapl_rsi.IsReady:
            return

        spy_close = float(data.Bars[self.spy].Close)
        aapl_close = float(data.Bars[self.aapl].Close)

        spy_sma_today = sum(self.spy_closes[i] for i in range(100)) / 100.0
        spy_sma_yesterday = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0
        spy_yesterday_close = self.spy_closes[1]

        spy_crosses_above = (
            spy_yesterday_close <= spy_sma_yesterday
            and spy_close > spy_sma_today
        )
        spy_crosses_below = (
            spy_yesterday_close >= spy_sma_yesterday
            and spy_close < spy_sma_today
        )

        # Sells before buys.
        if (
            self.strategy_a_lot > 0
            and not self.strategy_a_pending
            and spy_crosses_below
        ):
            self._submit_order(self.spy, -self.strategy_a_lot, "A")

        if (
            self.strategy_b_lot > 0
            and not self.strategy_b_pending
            and float(self.aapl_rsi.Current.Value) > 60
        ):
            self._submit_order(self.aapl, -self.strategy_b_lot, "B")

        if (
            self.strategy_a_lot == 0
            and not self.strategy_a_pending
            and spy_crosses_above
        ):
            target_value = float(self.Portfolio.TotalPortfolioValue) * self.strategy_a_percent
            quantity = int(math.floor(target_value / spy_close))

            if quantity > 0:
                self._submit_order(self.spy, quantity, "A")

        if (
            self.strategy_b_lot == 0
            and not self.strategy_b_pending
            and self.aapl_red_streak >= 3
            and float(self.Portfolio.Cash) >= 20_000
        ):
            quantity = int(math.floor(20_000 / aapl_close))

            if quantity > 0:
                self._submit_order(self.aapl, quantity, "B")

    def _submit_order(self, symbol, quantity, strategy):
        ticket = self.MarketOrder(symbol, quantity)
        order_id = ticket.OrderId

        self.pending_orders[order_id] = strategy

        if strategy == "A":
            self.strategy_a_pending = True
        else:
            self.strategy_b_pending = True

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId not in self.pending_orders:
            return

        strategy = self.pending_orders[order_event.OrderId]

        if order_event.FillQuantity != 0:
            if strategy == "A":
                self.strategy_a_lot += order_event.FillQuantity
            else:
                self.strategy_b_lot += order_event.FillQuantity

        if order_event.Status in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]:
            del self.pending_orders[order_event.OrderId]

            if strategy == "A":
                self.strategy_a_pending = False
            else:
                self.strategy_b_pending = False
